-- public.pick_wild(p_world uuid, p_x integer, p_y integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.pick_wild(p_world uuid, p_x integer, p_y integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare got text; v_ring boolean;
begin
  v_ring := in_safe_ring(p_world, p_x + 0.5, p_y + 0.5);
  select species into got from wild_table where not monster
    -- In the safe ring, none of the kinds it keeps out (`ring_keeps_out`).
    and not (v_ring and ring_keeps_out(species))
  order by random() / greatest(1e-9, weight) limit 1;
  return got;
end $function$
